mapper.update:
UPDATE users SET username = #{username}, password_hash = #{passwordHash}, nickname = #{nickname},
    avatar_ext = #{avatarExt}, api_key_cipher = #{apiKeyCipher}, api_key_nonce = #{apiKeyNonce},
    api_key_version = #{apiKeyVersion}, api_key_last4 = #{apiKeyLast4}, api_base = #{apiBase},
    model = #{model}, api_format = #{apiFormat}, temperature = #{temperature},
    created_at = #{createdAt}, updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE users SET summary_status = 'generating', summary_error = NULL,
    summary_started_at = #{now}
WHERE id = #{userId}
  AND (summary_status IS DISTINCT FROM 'generating' OR summary_started_at IS NULL
       OR summary_started_at < #{staleBefore})

UPDATE users SET summary_json = #{summaryJson}, summary_at = #{at}, summary_status = 'idle',
    summary_error = NULL, summary_started_at = NULL
WHERE id = #{userId}

mapper.select:
SELECT  FROM users
WHERE username LIKE '%' || #{query} || '%' OR nickname LIKE '%' || #{query} || '%'
ORDER BY username ASC LIMIT #{limit}
